function punGenerate(word, rng){
  word=String(word||'').trim(); if(!word) return {error:'请输入一个词'};
  rng=rng||Math.random;
  var tpl=[
    '一'+word+'钟情，再'+word+'倾心',
    word+'生'+word+'世，不离不弃',
    '今天的'+word+'，明天的'+word,
    word+'不可失，'+word+'不再来',
    '你这么'+word+'，一定是'+word+'二代',
    '没有什么比'+word+'更'+word+'的了'
  ];
  var n=Math.min(4,tpl.length); var out=[]; var used={};
  while(out.length<n){ var i=Math.floor(rng()*tpl.length); if(!used[i]){used[i]=1; out.push(tpl[i]);} }
  return {puns:out};
}
var EXPORTS={punGenerate:punGenerate};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.PunForgePure = EXPORTS; }
